      const list = [...pages.values()]
        .sort((a, b) => (a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0))
        .map((rec) => ({ slug: rec.slug, title: rec.title, body: rec.body, tags: rec.tags, version: rec.version }));
