  }).join('');
  view.innerHTML = `
    <h2>History: ${esc(slug)}</h2>
    <table class="history"><thead><tr><th>Version</th><th>Title</th><th>Updated</th><th></th><th></th><th></th></tr></thead>
    <tbody>${rows}</tbody></table>
    <p><a href="#/page/${encodeURIComponent(slug)}">Back to page</a></p>`;
